struct RNG_Int { int operator()() { return 10; } };
struct RNG_Double { double operator()(int) const { return 1.0; } };

template <typename Gen, typename... Args>
auto invoke_poly(Gen&& g, Args&&... a)
-> decltype(std::forward<Gen>(g)(std::forward<Args>(a)...))
{
    // Compiler determines return type (decltype) and optimal call
    return std::forward<Gen>(g)(std::forward<Args>(a)...);
}

// Result types determined at compile-time:
auto val_i = invoke_poly(RNG_Int{});      // int
auto val_d = invoke_poly(RNG_Double{}, 5);// double
